export type Role = "user" | "assistant";
export type Message = { id: string; role: Role; text: string; rating?: "up" | "down" };
export type Chat = { id: string; title: string; group: "Today" | "Yesterday" | "Earlier"; project?: string; messages: Message[] };
export type Project = { slug: string; name: string };

export const MODELS = [
  { id: "pro", name: "Aria Pro", note: "Best for hard problems" },
  { id: "fast", name: "Aria Fast", note: "Quick everyday answers" },
  { id: "mini", name: "Aria Mini", note: "Light and low cost" },
];

export const TOOLS = ["Web search", "Code interpreter", "Image generation", "File analysis"];
export const CHIPS = ["Deep Search", "Create Images", "Latest News", "Generate Video"] as const;

export const PROJECTS: Project[] = [
  { slug: "atlas", name: "Atlas" },
  { slug: "harbor", name: "Harbor" },
  { slug: "fieldnotes", name: "Fieldnotes" },
  { slug: "northwind", name: "Northwind" },
];

const m = (id: string, role: Role, text: string): Message => ({ id, role, text });

export const SEED: Chat[] = [
  { id: "hi", title: "hi", group: "Today", messages: [m("a", "user", "hi"), m("b", "assistant", "Hello! How can I help you today?")] },
  {
    id: "getting-started",
    title: "Getting Started Conversation",
    group: "Today",
    messages: [
      m("c", "user", "What do you think about the future of AI?"),
      m("d", "assistant", "The future of AI is incredibly promising, with potential breakthroughs in healthcare, education, and sustainability. However, it also requires careful ethical consideration, from how data is used to who benefits from the technology."),
    ],
  },
  { id: "ai-inspirations", title: "AI Inspirations", group: "Yesterday", messages: [m("e", "user", "Give me three ideas for an AI side project."), m("f", "assistant", "1. A study buddy that turns your notes into quizzes.\n2. A recipe planner that works from what is in your fridge.\n3. A meeting recap tool that lists decisions and owners.")] },
  { id: "analytics-report", title: "Analytics Report", group: "Yesterday", messages: [m("g", "user", "Summarise last month's traffic in two lines."), m("h", "assistant", "Traffic grew 12% month over month, led by organic search. Sign-ups held steady, so the conversion rate dipped slightly.")] },
  { id: "project-overview", title: "Project Overview", group: "Yesterday", messages: [m("i", "user", "Outline a project overview for a new onboarding flow."), m("j", "assistant", "Goal: get a new user to their first success in under five minutes.\nScope: welcome, one setup question, a guided first task.\nRisks: too many steps, unclear copy.\nMeasure: completion rate and time to first success.")] },
  ...[
    ["atlas", ["Roadmap brainstorm", "Release notes draft", "User interview themes"]],
    ["harbor", ["Pricing experiments", "Support macros"]],
    ["fieldnotes", ["Launch email", "Landing page copy", "Changelog tone", "FAQ rewrite"]],
    ["northwind", ["Quarterly review", "Hiring plan", "Vendor comparison"]],
  ].flatMap(([slug, titles]) =>
    (titles as string[]).map((t, i) => ({
      id: `${slug}-${i}`,
      title: t,
      group: "Earlier" as const,
      project: slug as string,
      messages: [m(`${slug}-${i}-u`, "user", t), m(`${slug}-${i}-a`, "assistant", `Here is a starting point for “${t}”. Tell me who it is for and I will tailor the tone and length.`)],
    }))
  ),
];

const REPLIES: [RegExp, string][] = [
  [/poem|haiku/i, "Leaves let go in gold,\nthe morning air holds its breath,\nthe year softly turns."],
  [/email/i, "Subject: A quick update\n\nHi there,\n\nHere is the short version: we shipped what we promised, and one more thing you will like. Reply if you want the details.\n\nThanks,\nThe team"],
  [/plan|week|schedule/i, "Here is a simple shape for it:\n\n• Two focused blocks each morning, no meetings\n• One admin hour after lunch\n• Friday afternoon for review and planning\n\nWant me to turn this into a calendar?"],
  [/code|react|bug|error/i, "Start by reproducing it with the smallest example you can. Then check the state that changes right before it breaks, and log it. Most bugs show up as one value that is not what you assumed."],
];

export const replyFor = (q: string, tool: string | null) => {
  const hit = REPLIES.find(([re]) => re.test(q));
  const lead = tool ? `(${tool})\n` : "";
  return lead + (hit ? hit[1] : `Here is a first answer to “${q.length > 70 ? q.slice(0, 67) + "…" : q}”.\n\nStart with the main point, then give two short reasons. I can go deeper on any part, or rewrite it for a different audience.`);
};

"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { usePathname, useRouter } from "next/navigation";
import { replyFor, SEED, type Chat } from "./data";

type Store = {
  chats: Chat[];
  busyId: string | null;
  toast: string;
  say: (t: string) => void;
  send: (chatId: string | null, text: string, tool?: string | null) => void;
  regenerate: (chatId: string, messageId: string) => void;
  rate: (chatId: string, messageId: string, rating: "up" | "down") => void;
  editAndResend: (chatId: string, messageId: string, text: string) => void;
  rename: (chatId: string, title: string) => void;
  remove: (chatId: string) => void;
};

const Ctx = createContext<Store | null>(null);
let counter = 1;
const uid = () => `n${Date.now().toString(36)}${counter++}`;

/** Keeps every conversation in memory and streams replies. Replace the stream with a call to your own model API. */
export function ChatProvider({ children }: { children: ReactNode }) {
  const router = useRouter();
  const base = useBase();
  const [chats, setChats] = useState<Chat[]>(SEED);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [toast, setToast] = useState("");
  const timer = useRef<number | null>(null);

  useEffect(() => () => { if (timer.current) window.clearInterval(timer.current); }, []);

  const say = useCallback((t: string) => {
    setToast(t);
    window.setTimeout(() => setToast((x) => (x === t ? "" : x)), 2200);
  }, []);

  const patch = useCallback((id: string, fn: (c: Chat) => Chat) => setChats((cur) => cur.map((c) => (c.id === id ? fn(c) : c))), []);

  const stream = useCallback(
    (chatId: string, assistantId: string, full: string) => {
      setBusyId(chatId);
      let i = 0;
      window.setTimeout(() => {
        timer.current = window.setInterval(() => {
          i = Math.min(full.length, i + 3);
          patch(chatId, (c) => ({ ...c, messages: c.messages.map((m) => (m.id === assistantId ? { ...m, text: full.slice(0, i) } : m)) }));
          if (i >= full.length) {
            if (timer.current) window.clearInterval(timer.current);
            setBusyId(null);
          }
        }, 18);
      }, 700);
    },
    [patch]
  );

  const value = useMemo<Store>(
    () => ({
      chats,
      busyId,
      toast,
      say,
      send: (chatId, text, tool = null) => {
        const q = text.trim();
        if (!q || busyId) return;
        const aId = uid();
        const full = replyFor(q, tool);
        let id = chatId;
        if (!id) {
          id = uid();
          const created: Chat = { id, title: q.length > 32 ? q.slice(0, 30) + "…" : q, group: "Today", messages: [] };
          setChats((c) => [created, ...c]);
          router.push(`${base}/c/${id}`);
        }
        patch(id, (c) => ({ ...c, messages: [...c.messages, { id: uid(), role: "user", text: q }, { id: aId, role: "assistant", text: "" }] }));
        stream(id, aId, full);
      },
      regenerate: (chatId, messageId) => {
        if (busyId) return;
        const chat = chats.find((c) => c.id === chatId);
        const idx = chat?.messages.findIndex((m) => m.id === messageId) ?? -1;
        const q = idx > 0 ? chat!.messages[idx - 1].text : "";
        patch(chatId, (c) => ({ ...c, messages: c.messages.map((m) => (m.id === messageId ? { ...m, text: "", rating: undefined } : m)) }));
        stream(chatId, messageId, replyFor(q + " ", null));
      },
      rate: (chatId, messageId, rating) => patch(chatId, (c) => ({ ...c, messages: c.messages.map((m) => (m.id === messageId ? { ...m, rating: m.rating === rating ? undefined : rating } : m)) })),
      editAndResend: (chatId, messageId, text) => {
        if (busyId || !text.trim()) return;
        const aId = uid();
        patch(chatId, (c) => {
          const idx = c.messages.findIndex((m) => m.id === messageId);
          return { ...c, messages: [...c.messages.slice(0, idx), { id: uid(), role: "user", text: text.trim() }, { id: aId, role: "assistant", text: "" }] };
        });
        stream(chatId, aId, replyFor(text.trim(), null));
      },
      rename: (chatId, title) => patch(chatId, (c) => ({ ...c, title })),
      remove: (chatId) => {
        setChats((c) => c.filter((x) => x.id !== chatId));
        say("Conversation deleted");
      },
    }),
    [chats, busyId, toast, say, patch, stream, router, base]
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useChats() {
  const v = useContext(Ctx);
  if (!v) throw new Error("useChats must be used inside ChatProvider");
  return v;
}

/** The URL prefix the template is mounted on, found from the current path so it works anywhere. */
export function useBase() {
  const path = usePathname();
  const i = path.indexOf("/ai-chat");
  return i === -1 ? "" : path.slice(0, i + "/ai-chat".length);
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import Link from "next/link";
import { useParams, usePathname, useRouter } from "next/navigation";
import { AnimatePresence, motion } from "framer-motion";
import { FolderPlus, Folder, Menu, MoreVertical, Pencil, PanelLeft, Search, SquarePen, Sparkles, Trash2, X } from "lucide-react";
import { PROJECTS } from "@/lib/ai-chat/data";
import { ChatProvider, useBase, useChats } from "@/lib/ai-chat/store";
import { cn } from "@/lib/utils";

export function Logo({ className }: { className?: string }) {
  return (
    <span className={cn("grid size-8 place-items-center rounded-full bg-primary text-primary-foreground", className)}>
      <Sparkles className="size-4" />
    </span>
  );
}

function SearchModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const s = useChats();
  const base = useBase();
  const [q, setQ] = useState("");
  const hits = useMemo(() => s.chats.filter((c) => c.title.toLowerCase().includes(q.trim().toLowerCase())).slice(0, 8), [s.chats, q]);
  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  return (
    <AnimatePresence>
      {open && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[70] grid place-items-start justify-center bg-foreground/20 p-4 pt-[14vh] backdrop-blur-sm" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
          <motion.div initial={{ opacity: 0, y: -10, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0 }} className="w-full max-w-lg overflow-hidden rounded-2xl border bg-card shadow-2xl">
            <label className="flex h-14 items-center gap-3 border-b px-4">
              <Search className="size-4 text-muted-foreground" />
              <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search conversations" className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground" />
            </label>
            <ul className="max-h-72 overflow-y-auto p-2">
              {hits.map((c) => (
                <li key={c.id}>
                  <Link href={`${base}/c/${c.id}`} onClick={onClose} className="flex items-center justify-between rounded-xl px-3 py-2.5 text-sm hover:bg-accent">
                    <span className="truncate">{c.title}</span>
                    <span className="ml-3 shrink-0 text-xs text-muted-foreground">{c.group}</span>
                  </Link>
                </li>
              ))}
              {hits.length === 0 && <li className="px-3 py-8 text-center text-sm text-muted-foreground">No conversations match.</li>}
            </ul>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

function ChatRow({ id, title, active }: { id: string; title: string; active: boolean }) {
  const s = useChats();
  const base = useBase();
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(title);
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const d = (e: MouseEvent) => !root.current?.contains(e.target as Node) && setOpen(false);
    document.addEventListener("mousedown", d);
    return () => document.removeEventListener("mousedown", d);
  }, [open]);

  if (editing)
    return (
      <form onSubmit={(e) => { e.preventDefault(); if (name.trim()) s.rename(id, name.trim()); setEditing(false); }} className="px-1">
        <input autoFocus value={name} onChange={(e) => setName(e.target.value)} onBlur={() => setEditing(false)} className="h-9 w-full rounded-lg border bg-background px-2.5 text-sm outline-none focus:ring-2 focus:ring-ring/30" />
      </form>
    );
  return (
    <div ref={root} className={cn("group relative flex items-center rounded-lg", active ? "bg-accent" : "hover:bg-accent/60")}>
      <Link href={`${base}/c/${id}`} className={cn("min-w-0 flex-1 truncate px-3 py-2 text-sm", active ? "text-foreground" : "text-muted-foreground group-hover:text-foreground")}>
        {title}
      </Link>
      <button type="button" aria-label="Chat options" aria-expanded={open} onClick={() => setOpen((o) => !o)} className={cn("mr-1 grid size-7 place-items-center rounded-md text-muted-foreground hover:text-foreground", open || active ? "opacity-100" : "opacity-0 group-hover:opacity-100")}>
        <MoreVertical className="size-4" />
      </button>
      {open && (
        <ul className="absolute right-0 top-9 z-30 w-40 rounded-xl border bg-card p-1 shadow-xl">
          <li><button type="button" onClick={() => { setOpen(false); setName(title); setEditing(true); }} className="flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-sm hover:bg-accent"><Pencil className="size-3.5" /> Rename</button></li>
          <li><button type="button" onClick={() => { setOpen(false); s.remove(id); if (active) router.push(base || "/"); }} className="flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-sm text-destructive hover:bg-destructive/10"><Trash2 className="size-3.5" /> Delete</button></li>
        </ul>
      )}
    </div>
  );
}

function Sidebar({ collapsed, setCollapsed, mobileOpen, closeMobile, openSearch }: { collapsed: boolean; setCollapsed: (v: boolean) => void; mobileOpen: boolean; closeMobile: () => void; openSearch: () => void }) {
  const s = useChats();
  const base = useBase();
  const params = useParams<{ id?: string; slug?: string }>();
  const path = usePathname();
  const router = useRouter();
  const history = s.chats.filter((c) => c.group !== "Earlier");
  const groups = (["Today", "Yesterday"] as const).map((g) => [g, history.filter((c) => c.group === g)] as const).filter(([, l]) => l.length);

  const body = (
    <div className="flex h-full w-[264px] flex-col p-4">
      <div className="flex items-center justify-between pb-5">
        <Link href={base || "/"} className="flex items-center gap-2.5" onClick={closeMobile}>
          <Logo />
          <span className="text-lg font-medium tracking-tight">Converse</span>
        </Link>
        <button type="button" aria-label="Collapse sidebar" onClick={() => (mobileOpen ? closeMobile() : setCollapsed(true))} className="grid size-8 place-items-center rounded-lg text-muted-foreground hover:bg-accent hover:text-foreground">
          {mobileOpen ? <X className="size-4" /> : <PanelLeft className="size-4" />}
        </button>
      </div>
      <button type="button" onClick={() => { router.push(base || "/"); closeMobile(); }} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-foreground/80 transition-colors hover:bg-accent">
        <SquarePen className="size-4" /> New Chat
      </button>
      <button type="button" onClick={() => { openSearch(); closeMobile(); }} className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-foreground/80 transition-colors hover:bg-accent">
        <Search className="size-4" /> Search
      </button>

      <div className="mt-5 flex items-center justify-between px-3 pb-2">
        <p className="text-sm text-muted-foreground">Projects</p>
        <button type="button" aria-label="New project" onClick={() => s.say("Projects are created from your own backend")} className="grid size-8 place-items-center rounded-lg border text-muted-foreground hover:bg-accent hover:text-foreground"><FolderPlus className="size-4" /></button>
      </div>
      <nav aria-label="Projects" className="space-y-0.5">
        {PROJECTS.map((p) => {
          const n = s.chats.filter((c) => c.project === p.slug).length;
          const active = path.includes(`/projects/${p.slug}`) || params.slug === p.slug;
          return (
            <Link key={p.slug} href={`${base}/projects/${p.slug}`} onClick={closeMobile} className={cn("flex items-center gap-3 rounded-lg px-3 py-2 text-sm transition-colors", active ? "bg-accent text-foreground" : "text-muted-foreground hover:bg-accent/60 hover:text-foreground")}>
              <Folder className="size-4" />
              <span className="flex-1">{p.name}</span>
              <span className="rounded-md bg-muted px-1.5 py-0.5 text-[11px] tabular-nums">{String(n).padStart(2, "0")}</span>
            </Link>
          );
        })}
      </nav>

      <div className="mt-5 min-h-0 flex-1 space-y-4 overflow-y-auto pr-1">
        {groups.map(([g, list]) => (
          <div key={g}>
            <p className="px-3 pb-1.5 text-[11px] font-medium uppercase tracking-widest text-muted-foreground">{g}</p>
            <div className="space-y-0.5">
              {list.map((c) => (
                <ChatRow key={c.id} id={c.id} title={c.title} active={params.id === c.id} />
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="mt-3 flex items-center gap-3 rounded-2xl bg-gradient-to-r from-accent to-primary/25 p-2.5">
        <span className="grid size-10 shrink-0 place-items-center rounded-full bg-card text-xs font-semibold">AM</span>
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-medium">Alex Morgan</p>
          <p className="text-xs text-muted-foreground">Free</p>
        </div>
        <button type="button" className="rounded-full bg-card px-3.5 py-1.5 text-sm font-medium shadow-sm transition-colors hover:bg-background">Upgrade</button>
      </div>
    </div>
  );

  return (
    <>
      <aside className={cn("hidden shrink-0 overflow-hidden transition-[width] duration-300 lg:block", collapsed ? "w-0" : "w-[264px]")}>{body}</aside>
      <AnimatePresence>
        {mobileOpen && (
          <>
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={closeMobile} className="fixed inset-0 z-40 bg-foreground/30 lg:hidden" />
            <motion.aside initial={{ x: -280 }} animate={{ x: 0 }} exit={{ x: -280 }} transition={{ duration: 0.25 }} className="fixed inset-y-0 left-0 z-50 bg-muted lg:hidden">{body}</motion.aside>
          </>
        )}
      </AnimatePresence>
    </>
  );
}

function Frame({ children }: { children: ReactNode }) {
  const s = useChats();
  const [collapsed, setCollapsed] = useState(false);
  const [mobile, setMobile] = useState(false);
  const [search, setSearch] = useState(false);
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setSearch((v) => !v); }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, []);
  return (
    <div className="flex h-full min-h-[34rem] w-full bg-muted p-0 text-foreground lg:p-2">
      <Sidebar collapsed={collapsed} setCollapsed={setCollapsed} mobileOpen={mobile} closeMobile={() => setMobile(false)} openSearch={() => setSearch(true)} />
      <div className="relative flex min-w-0 flex-1 flex-col overflow-hidden bg-card lg:rounded-2xl">
        <div className="absolute left-3 top-3 z-10 flex gap-1">
          <button type="button" aria-label="Open menu" onClick={() => setMobile(true)} className="grid size-9 place-items-center rounded-lg text-muted-foreground hover:bg-accent hover:text-foreground lg:hidden"><Menu className="size-[18px]" /></button>
          {collapsed && (
            <button type="button" aria-label="Expand sidebar" onClick={() => setCollapsed(false)} className="hidden size-9 place-items-center rounded-lg text-muted-foreground hover:bg-accent hover:text-foreground lg:grid"><PanelLeft className="size-[18px]" /></button>
          )}
        </div>
        {children}
        <AnimatePresence>
          {s.toast && (
            <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} role="status" className="absolute bottom-24 left-1/2 z-50 -translate-x-1/2 rounded-full bg-foreground px-4 py-2 text-sm text-background shadow-lg">{s.toast}</motion.p>
          )}
        </AnimatePresence>
      </div>
      <SearchModal open={search} onClose={() => setSearch(false)} />
    </div>
  );
}

/** The whole app shell. Wrap every page of the chat in this, from a layout file. */
export function ChatShell({ children }: { children: ReactNode }) {
  return (
    <ChatProvider>
      <Frame>{children}</Frame>
    </ChatProvider>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { notFound } from "next/navigation";
import { AnimatePresence, motion } from "framer-motion";
import { ArrowUp, Check, ChevronDown, Copy, Ellipsis, FileText, Image as ImageIcon, Newspaper, Paperclip, Pencil, Play, RefreshCw, Search, Share2, SlidersHorizontal, Sparkles, ThumbsDown, ThumbsUp, X } from "lucide-react";
import { CHIPS, MODELS, PROJECTS, TOOLS } from "@/lib/ai-chat/data";
import { useBase, useChats } from "@/lib/ai-chat/store";
import { cn } from "@/lib/utils";

const CHIP_ICON = { "Deep Search": Search, "Create Images": ImageIcon, "Latest News": Newspaper, "Generate Video": Play };

function useOutside(open: boolean, close: () => void) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const d = (e: MouseEvent) => !ref.current?.contains(e.target as Node) && close();
    document.addEventListener("mousedown", d);
    return () => document.removeEventListener("mousedown", d);
  }, [open, close]);
  return ref;
}

function Composer({ chatId, draftTool, setDraftTool, text, setText, autoFocus }: { chatId: string | null; draftTool: string | null; setDraftTool: (t: string | null) => void; text: string; setText: (t: string) => void; autoFocus?: boolean }) {
  const s = useChats();
  const [model, setModel] = useState(MODELS[1].id);
  const [menu, setMenu] = useState<null | "tools" | "model">(null);
  const [file, setFile] = useState<string | null>(null);
  const area = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const root = useOutside(menu !== null, () => setMenu(null));
  const current = MODELS.find((m) => m.id === model)!;
  const busy = s.busyId !== null;

  useEffect(() => {
    if (!area.current) return;
    area.current.style.height = "0px";
    area.current.style.height = `${Math.min(area.current.scrollHeight, 180)}px`;
  }, [text]);

  const submit = () => {
    if (!text.trim() || busy) return;
    s.send(chatId, file ? `${text} (attached: ${file})` : text, draftTool);
    setText("");
    setFile(null);
    setDraftTool(null);
  };

  return (
    <div ref={root} className="relative w-full rounded-3xl border bg-card p-4 shadow-[0_8px_30px_-12px_rgba(20,30,60,0.18)] transition-shadow focus-within:shadow-[0_12px_40px_-12px_rgba(60,90,255,0.25)]">
      {(draftTool || file) && (
        <div className="mb-2 flex flex-wrap gap-2">
          {draftTool && (
            <span className="inline-flex items-center gap-1.5 rounded-full bg-accent px-3 py-1 text-xs">
              {draftTool}
              <button type="button" aria-label="Remove tool" onClick={() => setDraftTool(null)}><X className="size-3" /></button>
            </span>
          )}
          {file && (
            <span className="inline-flex items-center gap-1.5 rounded-full bg-accent px-3 py-1 text-xs">
              <FileText className="size-3" /> {file}
              <button type="button" aria-label="Remove file" onClick={() => setFile(null)}><X className="size-3" /></button>
            </span>
          )}
        </div>
      )}
      <textarea
        ref={area}
        autoFocus={autoFocus}
        value={text}
        rows={1}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.shiftKey) {
            e.preventDefault();
            submit();
          }
        }}
        placeholder="Ask me anything..."
        className="block max-h-44 w-full resize-none bg-transparent text-[15px] outline-none placeholder:text-muted-foreground"
      />
      <div className="mt-4 flex items-center justify-between gap-3">
        <div className="relative flex items-center gap-1">
          <button type="button" aria-label="Attach a file" onClick={() => fileInput.current?.click()} className="grid size-9 place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground">
            <Paperclip className="size-[18px]" />
          </button>
          <input ref={fileInput} type="file" hidden onChange={(e) => setFile(e.target.files?.[0]?.name ?? null)} />
          <button type="button" aria-haspopup="menu" aria-expanded={menu === "tools"} onClick={() => setMenu(menu === "tools" ? null : "tools")} className="inline-flex h-9 items-center gap-2 rounded-full px-3 text-sm text-foreground/80 transition-colors hover:bg-accent">
            <SlidersHorizontal className="size-4" /> Tools
          </button>
          <AnimatePresence>
            {menu === "tools" && (
              <motion.ul initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="absolute bottom-12 left-0 z-20 w-56 rounded-2xl border bg-card p-1.5 shadow-xl">
                {TOOLS.map((t) => (
                  <li key={t}>
                    <button type="button" onClick={() => { setDraftTool(draftTool === t ? null : t); setMenu(null); }} className="flex w-full items-center justify-between rounded-xl px-3 py-2 text-sm hover:bg-accent">
                      {t}
                      {draftTool === t && <Check className="size-4 text-primary" />}
                    </button>
                  </li>
                ))}
              </motion.ul>
            )}
          </AnimatePresence>
        </div>
        <div className="relative flex items-center gap-2">
          <button type="button" aria-haspopup="listbox" aria-expanded={menu === "model"} onClick={() => setMenu(menu === "model" ? null : "model")} className="inline-flex h-9 items-center gap-2 rounded-full px-3 text-sm transition-colors hover:bg-accent">
            <Sparkles className="size-3.5 text-chart-2" /> {current.name} <ChevronDown className={cn("size-4 transition-transform", menu === "model" && "rotate-180")} />
          </button>
          <AnimatePresence>
            {menu === "model" && (
              <motion.ul role="listbox" initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="absolute bottom-12 right-0 z-20 w-64 rounded-2xl border bg-card p-1.5 shadow-xl">
                {MODELS.map((m) => (
                  <li key={m.id}>
                    <button type="button" role="option" aria-selected={m.id === model} onClick={() => { setModel(m.id); setMenu(null); }} className="flex w-full items-start gap-2 rounded-xl px-3 py-2 text-left hover:bg-accent">
                      <Check className={cn("mt-0.5 size-4 shrink-0 text-primary", m.id === model ? "opacity-100" : "opacity-0")} />
                      <span>
                        <span className="block text-sm font-medium">{m.name}</span>
                        <span className="block text-xs text-muted-foreground">{m.note}</span>
                      </span>
                    </button>
                  </li>
                ))}
              </motion.ul>
            )}
          </AnimatePresence>
          <button type="button" aria-label="Send" onClick={submit} disabled={!text.trim() || busy} className="grid size-10 place-items-center rounded-full bg-primary text-primary-foreground transition-all duration-300 hover:scale-105 disabled:scale-100 disabled:bg-muted disabled:text-muted-foreground">
            <ArrowUp className="size-[18px]" />
          </button>
        </div>
      </div>
    </div>
  );
}

